const crypto = require("crypto");

const headers = $json.headers || {};
const query = $json.query || {};

const fail = (httpStatus, error) => [{
  json: {
    ok: false,
    http_status: httpStatus,
    error
  }
}];

const accountId = String(query.account_id || "").trim();
const dateFrom = String(query.date_from || "").trim();
const dateTo = String(query.date_to || "").trim();
const includeDescendants = String(query.include_descendants ?? "true").toLowerCase() !== "false";

const parseCategoryIds = (key, errorCode) => {
  if (!Object.prototype.hasOwnProperty.call(query, key)) return null;
  const raw = String(query[key] ?? "").trim();
  if (!raw) return [];
  if (!/^\d+(,\d+)*$/.test(raw)) {
    throw new Error(errorCode);
  }
  return [...new Set(raw.split(",").map((value) => Number(value)))];
};

let incomeCategoryIds;
let expenseCategoryIds;
try {
  incomeCategoryIds = parseCategoryIds("income_category_ids", "INCOME_CATEGORY_IDS_INVALID");
  expenseCategoryIds = parseCategoryIds("expense_category_ids", "EXPENSE_CATEGORY_IDS_INVALID");
} catch (error) {
  return fail(400, error.message);
}

const categoryPredicate = (ids, transactionTypes) => {
  if (ids === null) return null;
  if (!ids.length) return "false";
  const types = transactionTypes.map((value) => `'${value}'`).join(",");
  return `(t.transaction_type in (${types}) and t.category_id = any(ARRAY[${ids.join(",")}]::bigint[]))`;
};

const incomePredicate = categoryPredicate(incomeCategoryIds, ["income"]);
const expensePredicate = categoryPredicate(expenseCategoryIds, ["expense", "adjustment"]);
const categoryFilterPredicate = incomePredicate === null && expensePredicate === null
  ? "true"
  : `(${incomePredicate ?? "t.transaction_type = 'income'"} or ${expensePredicate ?? "t.transaction_type in ('expense','adjustment')"})`;

if (!accountId) return fail(400, "ACCOUNT_ID_REQUIRED");
if (!/^[A-Za-z0-9_-]{1,128}$/.test(accountId)) return fail(400, "ACCOUNT_ID_INVALID");
if (!/^\d{4}-\d{2}-\d{2}$/.test(dateFrom) || !/^\d{4}-\d{2}-\d{2}$/.test(dateTo)) {
  return fail(400, "DATE_RANGE_INVALID");
}
if (dateFrom > dateTo) return fail(400, "DATE_RANGE_INVALID");

const initData =
  headers["x-telegram-init-data"] ||
  headers["X-Telegram-Init-Data"] ||
  query.initData ||
  query.init_data ||
  null;

if (!initData) return fail(401, "INIT_DATA_MISSING");

const botToken = $env.MONEYTRACK_BOT_TOKEN;
if (!botToken) return fail(500, "BOT_TOKEN_MISSING");

function parseInitData(value) {
  const result = {};
  for (const part of value.split("&")) {
    const eqIndex = part.indexOf("=");
    if (eqIndex === -1) continue;
    const key = decodeURIComponent(part.slice(0, eqIndex));
    const itemValue = decodeURIComponent(part.slice(eqIndex + 1));
    result[key] = itemValue;
  }
  return result;
}

let params;
try {
  params = parseInitData(initData);
} catch {
  return fail(401, "INVALID_INIT_DATA");
}

const receivedHash = params.hash;
if (!receivedHash) return fail(401, "HASH_MISSING");
delete params.hash;

const dataCheckString = Object.keys(params)
  .sort()
  .map((key) => `${key}=${params[key]}`)
  .join("\n");

const secretKey = crypto
  .createHmac("sha256", "WebAppData")
  .update(botToken)
  .digest();
const calculatedHash = crypto
  .createHmac("sha256", secretKey)
  .update(dataCheckString)
  .digest("hex");

if (calculatedHash !== receivedHash) return fail(401, "INVALID_INIT_DATA_HASH");
if (!params.user) return fail(401, "USER_MISSING");

let user;
try {
  user = JSON.parse(params.user);
} catch {
  return fail(401, "INVALID_USER_DATA");
}

if (!user?.id) return fail(401, "INVALID_USER_DATA");

return [{
  json: {
    ok: true,
    telegram_user_id: user.id,
    account_id: accountId,
    date_from: dateFrom,
    date_to: dateTo,
    include_descendants: includeDescendants,
    income_category_ids: incomeCategoryIds,
    expense_category_ids: expenseCategoryIds,
    category_filter_predicate: categoryFilterPredicate
  }
}];

const row = $input.first().json;

if (!row || !row.user_id) {
  return [{ json: { ok: false, http_status: 404, error: "USER_NOT_FOUND" } }];
}
if (Number(row.account_scope_count || 0) === 0) {
  return [{ json: { ok: false, http_status: 404, error: "ACCOUNT_NOT_FOUND" } }];
}

return [{
  json: {
    ok: true,
    data: {
      account_id: row.account_id,
      include_descendants: row.include_descendants === true || row.include_descendants === "true",
      base_currency: row.base_currency,
      summary_currency: row.summary_currency || row.base_currency,
      period: {
        date_from: row.date_from,
        date_to: row.date_to
      },
      summary: {
        income: Number(row.income || 0),
        expense: Number(row.expense || 0),
        result: Number(row.result || 0),
        transfers: Number(row.transfers || 0),
        count: Number(row.count || 0),
        missing_rate_count: Number(row.missing_rate_count || 0)
      },
      transactions: row.transactions || []
    }
  }
}];
